  function detectLanguage() {
    // Prefer the local time zone as a privacy-friendly regional hint; no location permission or network request is used.
    try {
      const zone = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
      if (zone === "Asia/Ho_Chi_Minh") return "vi";
      if (zone === "Asia/Seoul") return "ko";
    } catch {}
    let locale = "";
    try { locale = (globalThis.browser?.i18n?.getUILanguage?.() || navigator.language || Intl.DateTimeFormat().resolvedOptions().locale || "en").toLowerCase(); } catch {}
    if (locale.startsWith("vi")) return "vi";
    if (locale.startsWith("ko")) return "ko";
    return "en";
  }
  function languageFor(settings) { return LANGS.some(x => x.code === settings?.language) ? settings.language : detectLanguage(); }
  function t(key, vars = {}, lang) {
    const code = LANGS.some(x => x.code === lang) ? lang : detectLanguage();
    let value = MESSAGES[code][key] ?? MESSAGES.en[key] ?? key;
    return String(value).replace(/\{(\w+)\}/g, (_, k) => vars[k] == null ? `{${k}}` : String(vars[k]));
  }
  globalThis.LHN_I18N = { LANGS, MESSAGES, detectLanguage, languageFor, t };
